import { Stack } from 'styled-system/jsx';
import { Text } from '~/components/ui/text';
import { Button } from '~/components/ui/button';

interface MonthYearListProps {
  monthsYears: Array<{ monthYear: string; count: number; firstTweetId: string }>;
  currentMonthYear: string | null;
  setSelectedMonthYear: (monthYear: string | null) => void;
  closeSidebar: () => void;
  language: string;
  latestTweetId: string | null;
  handleSelectTweet: (id: string) => void;
  formatMonthYear: (monthYear: string, language: string) => string;
  t: (key: string) => string;
}

export function MonthYearList({
  monthsYears,
  currentMonthYear,
  setSelectedMonthYear,
  closeSidebar,
  language,
  latestTweetId,
  handleSelectTweet,
  formatMonthYear,
  t
}: MonthYearListProps) {
  return (
    <Stack gap="1">
      {monthsYears.map((my) => (
        <Button
          data-active={currentMonthYear === my.monthYear ? 'true' : undefined}
          key={my.monthYear}
          variant="ghost"
          size="md"
          onClick={() => {
            if (currentMonthYear !== my.monthYear) {
              setSelectedMonthYear(my.monthYear);
            } else {
              setSelectedMonthYear(null);
            }
            closeSidebar();
          }}
          display="flex"
          flexDirection="row"
          justifyContent="flex-start"
          rowGap="0.5"
          flexWrap="wrap"
          _active={{ bg: 'bg.emphasized' }}
        >
          {formatMonthYear(my.monthYear, language)}
          {my.count > 0 && (
            <>
              {' '}
              <Text as="span" color="fg.subtle" fontSize="sm">
                ({my.count})
              </Text>
            </>
          )}
        </Button>
      ))}
      {latestTweetId && (
        <Button
          variant="ghost"
          size="md"
          onClick={() => {
            handleSelectTweet(latestTweetId);
            closeSidebar();
          }}
          justifyContent="flex-start"
          _active={{ bg: 'bg.emphasized' }}
        >
          {t('bluebird.readingMode.latest')}
        </Button>
      )}
    </Stack>
  );
}
